    {
      "activity_id": "ACT-1",
      "activity_name": "Create and configure separate repository for Lattice SPI (U2)",
      "activity_description": "Extract Lattice SPI code from the monolithic project into a new standalone repository, set up build scripts, dependency management, and initial CI workflows.",
      "most_likely_effort": 1.5
    },
    {
