    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Prepare and submit PR for Mesos SPI (U1)",
      "activity_description": "Perform code cleanup, ensure test coverage, write PR description, and submit the Pull Request for existing Mesos SPI work.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Core SPI UNDEPLOYED status model and strategy updates (U7)",
      "activity_description": "Add UNDEPLOYED enum value to DeploymentState in the core deployer contract and update common status determination logic for streams without deployment context.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Implement UNDEPLOYED status for Cloud Foundry SPI (U5)",
      "activity_description": "Update Cloud Foundry AppDeployer implementation to return UNDEPLOYED status when app deployment context is missing, updating corresponding unit tests.",
