      "most_likely_effort": 0.5
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Implement UNDEPLOYED status for Kubernetes SPI (U8)",
      "activity_description": "Update Kubernetes AppDeployer implementation and unit tests to return UNDEPLOYED when resource or deployment context is absent.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Cross-deployer integration testing and verification",
      "activity_description": "Execute integration tests across all SPI implementations to verify consistent behavior for undeployed streams and ensure backwards compatibility.",
